// Differential probe for the pinned NURBS addons:
// examples/jsm/curves/NURBSUtils.js, NURBSCurve.js, NURBSSurface.js and NURBSVolume.js.
//
// Protocol: one scenario per stdin line, tokens separated by spaces. The scenario list is
// generated by compare-nurbs.mjs, which replays the same calls against the pinned three.js
// modules, so the field order below is the single source of truth for both sides.
//
//   S <p> <u> <knotCount> <knots...>
//   B <span> <u> <p> <knotCount> <knots...>
//   P <p> <u> <knotCount> <knots...> <pointCount> <x y z w ...>
//   F <span> <u> <p> <n> <knotCount> <knots...>
//   D <p> <u> <nd> <knotCount> <knots...> <pointCount> <x y z w ...>
//   K <k> <i>
//   R <pointCount> <x y z w ...>
//   N <p> <u> <nd> <knotCount> <knots...> <pointCount> <x y z w ...>
//   U <p> <q> <u> <v> <UCount> <U...> <VCount> <V...> <rows> <cols> <x y z w ...>
//   V <p> <q> <r> <u> <v> <w> <UCount> <U...> <VCount> <V...> <WCount> <W...> <planes> <rows> <cols> <points...>
//   C <degree> <startPresent> <start> <endPresent> <end> <knotCount> <knots...> <pointCount> <points...> <tCount> <t...>
//   M <degree1> <degree2> <UCount> <U...> <VCount> <V...> <rows> <cols> <points...> <tCount> <t1 t2 ...>
//   L <d1> <d2> <d3> <UCount> <U...> <VCount> <V...> <WCount> <W...> <planes> <rows> <cols> <points...> <tCount> <t1 t2 t3 ...>
#include "core/JsonValue.h"
#include "curves/NURBSCurve.h"
#include "curves/NURBSSurface.h"
#include "curves/NURBSUtils.h"
#include "curves/NURBSVolume.h"
#include <charconv>
#include <cmath>
#include <cstddef>
#include <iostream>
#include <limits>
#include <sstream>
#include <string>
#include <vector>

namespace {
JsonValue number(double value) {
    if (std::isnan(value)) return "NaN";
    if (std::isinf(value)) return value < 0 ? "-Infinity" : "Infinity";
    if (value == 0 && std::signbit(value)) return "-0";
    return value;
}
JsonValue numbers(const std::vector<double>& values) {
    JsonValue::Array result;
    for (const auto value : values) result.push_back(number(value));
    return result;
}
JsonValue vectorJSON(const Vector3& value) { return JsonValue::Array{number(value.x), number(value.y), number(value.z)}; }
JsonValue vectorJSON(const Vector4& value) {
    return JsonValue::Array{number(value.x), number(value.y), number(value.z), number(value.w)};
}
double parse(const std::string& token) {
    if (token == "NaN") return std::numeric_limits<double>::quiet_NaN();
    if (token == "Infinity") return std::numeric_limits<double>::infinity();
    if (token == "-Infinity") return -std::numeric_limits<double>::infinity();
    if (token == "-0") return -0.;
    double value = 0;
    std::from_chars(token.data(), token.data() + token.size(), value);
    return value;
}
struct Reader {
    std::istringstream stream;
    explicit Reader(const std::string& line) : stream(line) {}
    std::string token() {
        std::string value;
        stream >> value;
        return value;
    }
    double numberToken() { return parse(token()); }
    std::size_t countToken() { return std::size_t(numberToken()); }
    std::vector<double> knots() {
        const std::size_t count = countToken();
        std::vector<double> values(count);
        for (std::size_t i = 0; i < count; ++i) values[i] = numberToken();
        return values;
    }
    std::vector<Vector4> points() {
        const std::size_t count = countToken();
        std::vector<Vector4> values;
        values.reserve(count);
        for (std::size_t i = 0; i < count; ++i) {
            const double x = numberToken(), y = numberToken(), z = numberToken(), w = numberToken();
            values.emplace_back(x, y, z, w);
        }
        return values;
    }
    NURBSUtils::ControlGrid grid(std::size_t rows) {
        const std::size_t columns = countToken();
        const std::vector<Vector4> flat = points();
        if (flat.size() < rows * columns) throw std::runtime_error("scenario grid is short");
        NURBSUtils::ControlGrid values(rows, NURBSUtils::ControlPoints(columns));
        for (std::size_t r = 0; r < rows; ++r)
            for (std::size_t c = 0; c < columns; ++c) values[r][c] = flat[r * columns + c];
        return values;
    }
};
JsonValue runScenario(const std::string& line, bool& failed) {
    Reader reader(line);
    const std::string kind = reader.token();
    failed = false;
    try {
        if (kind == "S") {
            const double p = reader.numberToken(), u = reader.numberToken();
            const auto knots = reader.knots();
            return JsonValue::Object{{"span", number(NURBSUtils::findSpan(p, u, knots))}};
        }
        if (kind == "B") {
            const double span = reader.numberToken(), u = reader.numberToken(), p = reader.numberToken();
            const auto knots = reader.knots();
            return JsonValue::Object{{"basis", numbers(NURBSUtils::calcBasisFunctions(span, u, p, knots))}};
        }
        if (kind == "P") {
            const double p = reader.numberToken(), u = reader.numberToken();
            const auto knots = reader.knots();
            const auto points = reader.points();
            return JsonValue::Object{{"point", vectorJSON(NURBSUtils::calcBSplinePoint(p, knots, points, u))}};
        }
        if (kind == "F") {
            const double span = reader.numberToken(), u = reader.numberToken(), p = reader.numberToken();
            const double n = reader.numberToken();
            const auto knots = reader.knots();
            JsonValue::Array rows;
            for (const auto& row : NURBSUtils::calcBasisFunctionDerivatives(span, u, p, n, knots)) rows.push_back(numbers(row));
            return JsonValue::Object{{"ders", std::move(rows)}};
        }
        if (kind == "D") {
            const double p = reader.numberToken(), u = reader.numberToken(), nd = reader.numberToken();
            const auto knots = reader.knots();
            const auto points = reader.points();
            JsonValue::Array rows;
            for (const auto& value : NURBSUtils::calcBSplineDerivatives(p, knots, points, u, nd))
                rows.push_back(vectorJSON(value));
            return JsonValue::Object{{"ders", std::move(rows)}};
        }
        if (kind == "K") {
            const double k = reader.numberToken(), i = reader.numberToken();
            return JsonValue::Object{{"value", number(NURBSUtils::calcKoverI(k, i))}};
        }
        if (kind == "R") {
            const auto points = reader.points();
            JsonValue::Array rows;
            for (const auto& value : NURBSUtils::calcRationalCurveDerivatives(points)) rows.push_back(vectorJSON(value));
            return JsonValue::Object{{"ders", std::move(rows)}};
        }
        if (kind == "N") {
            const double p = reader.numberToken(), u = reader.numberToken(), nd = reader.numberToken();
            const auto knots = reader.knots();
            const auto points = reader.points();
            JsonValue::Array rows;
            for (const auto& value : NURBSUtils::calcNURBSDerivatives(p, knots, points, u, nd)) rows.push_back(vectorJSON(value));
            return JsonValue::Object{{"ders", std::move(rows)}};
        }
        if (kind == "U") {
            const double p = reader.numberToken(), q = reader.numberToken();
            const double u = reader.numberToken(), v = reader.numberToken();
            const auto knotsU = reader.knots();
            const auto knotsV = reader.knots();
            const auto grid = reader.grid(reader.countToken());
            Vector3 target;
            NURBSUtils::calcSurfacePoint(p, q, knotsU, knotsV, grid, u, v, target);
            return JsonValue::Object{{"point", vectorJSON(target)}};
        }
        if (kind == "V") {
            const double p = reader.numberToken(), q = reader.numberToken(), r = reader.numberToken();
            const double u = reader.numberToken(), v = reader.numberToken(), w = reader.numberToken();
            const auto knotsU = reader.knots();
            const auto knotsV = reader.knots();
            const auto knotsW = reader.knots();
            const std::size_t planes = reader.countToken();
            NURBSUtils::ControlVolume volume;
            for (std::size_t i = 0; i < planes; ++i) volume.push_back(reader.grid(reader.countToken()));
            Vector3 target;
            NURBSUtils::calcVolumePoint(p, q, r, knotsU, knotsV, knotsW, volume, u, v, w, target);
            return JsonValue::Object{{"point", vectorJSON(target)}};
        }
        if (kind == "C") {
            const double degree = reader.numberToken();
            const bool hasStart = reader.numberToken() != 0;
            const double start = reader.numberToken();
            const bool hasEnd = reader.numberToken() != 0;
            const double end = reader.numberToken();
            auto knots = reader.knots();
            auto points = reader.points();
            NURBSCurve curve(degree, std::move(knots), std::move(points),
                hasStart ? JSValue(start) : JSValue(), hasEnd ? JSValue(end) : JSValue());
            const std::size_t times = reader.countToken();
            JsonValue::Array sampled, tangents;
            Vector3 target;
            for (std::size_t i = 0; i < times; ++i) {
                const double t = reader.numberToken();
                curve.getPoint(t, target);
                sampled.push_back(vectorJSON(target));
                curve.getTangent(t, target);
                tangents.push_back(vectorJSON(target));
            }
            const JsonValue json = curve.toJSON();
            JsonValue::Array jsonPoints;
            for (const auto& entry : json.at("controlPoints").get<JsonValue::Array>()) {
                JsonValue::Array components;
                for (const auto& value : entry.get<JsonValue::Array>()) components.push_back(number(value.get<double>()));
                jsonPoints.push_back(std::move(components));
            }
            JsonValue::Array jsonKnots;
            for (const auto& value : json.at("knots").get<JsonValue::Array>()) jsonKnots.push_back(number(value.get<double>()));
            auto clone = curve.clone();
            auto typed = std::dynamic_pointer_cast<NURBSCurve>(clone);
            if (!typed) throw std::runtime_error("clone is not a NURBSCurve");
            // The upstream copy clones every control point: editing the copy must not
            // reach the original curve.
            const double original = curve.controlPoints.empty() ? 0. : curve.controlPoints[0].x;
            if (!typed->controlPoints.empty()) typed->controlPoints[0].x = 99.;
            const bool independent = typed->controlPoints.empty() || curve.controlPoints.empty() ||
                                     curve.controlPoints[0].x == original;
            JsonValue copy = JsonValue::Object{{"degree", number(typed->degree)},
                {"controlCount", number(double(typed->controlPoints.size()))},
                {"startKnot", number(typed->startKnot)}, {"endKnot", number(typed->endKnot)},
                {"independent", independent}, {"arcLengthDivisions", number(typed->arcLengthDivisions)}};
            return JsonValue::Object{{"startKnot", number(curve.startKnot)}, {"endKnot", number(curve.endKnot)},
                {"points", std::move(sampled)}, {"tangents", std::move(tangents)},
                {"json", JsonValue::Object{{"degree", number(json.at("degree").get<double>())},
                    {"knots", std::move(jsonKnots)}, {"controlPoints", std::move(jsonPoints)},
                    {"startKnot", number(json.at("startKnot").get<double>())},
                    {"endKnot", number(json.at("endKnot").get<double>())}}},
                {"copy", std::move(copy)}};
        }
        if (kind == "M") {
            const double degree1 = reader.numberToken(), degree2 = reader.numberToken();
            auto knots1 = reader.knots();
            auto knots2 = reader.knots();
            const std::size_t rows = reader.countToken();
            auto grid = reader.grid(rows);
            NURBSSurface surface(degree1, degree2, std::move(knots1), std::move(knots2), grid);
            const std::size_t times = reader.countToken();
            Vector3 target, first;
            bool sampled = false;
            for (std::size_t i = 0; i < times; ++i) {
                const double t1 = reader.numberToken(), t2 = reader.numberToken();
                surface.getPoint(t1, t2, target);
                if (!sampled) { first = target; sampled = true; }
            }
            return JsonValue::Object{{"point", vectorJSON(first)},
                {"shape", JsonValue::Array{number(double(surface.controlPoints.size())),
                    number(double(surface.controlPoints.empty() ? 0 : surface.controlPoints[0].size()))}}};
        }
        if (kind == "L") {
            const double degree1 = reader.numberToken(), degree2 = reader.numberToken(), degree3 = reader.numberToken();
            auto knots1 = reader.knots();
            auto knots2 = reader.knots();
            auto knots3 = reader.knots();
            const std::size_t planes = reader.countToken();
            std::vector<NURBSUtils::ControlGrid> grid(planes);
            for (std::size_t p = 0; p < planes; ++p) grid[p] = reader.grid(reader.countToken());
            NURBSVolume volume(degree1, degree2, degree3, std::move(knots1), std::move(knots2), std::move(knots3), grid);
            Vector3 target, first;
            const std::size_t times = reader.countToken();
            for (std::size_t i = 0; i < times; ++i) {
                const double t1 = reader.numberToken(), t2 = reader.numberToken(), t3 = reader.numberToken();
                volume.getPoint(t1, t2, t3, target);
                if (i == 0) first = target;
            }
            return JsonValue::Object{{"point", vectorJSON(first)},
                {"shape", JsonValue::Array{number(double(volume.controlPoints.size())),
                    number(double(volume.controlPoints.empty() ? 0 : volume.controlPoints[0].size())),
                    number(double(volume.controlPoints.empty() || volume.controlPoints[0].empty()
                                      ? 0 : volume.controlPoints[0][0].size()))}}};
        }
    } catch (const JSTypeError&) {
        failed = true;
        return JsonValue::Object{{"error", "TypeError"}};
    } catch (const JSRangeError&) {
        failed = true;
        return JsonValue::Object{{"error", "RangeError"}};
    }
    throw std::runtime_error("unknown scenario kind: " + kind);
}
}

int main() {
    std::string line;
    while (std::getline(std::cin, line)) {
        bool failed = false;
        try {
            std::cout << runScenario(line, failed).dump() << '\n';
        } catch (const std::exception& error) {
            std::cout << JsonValue(JsonValue::Object{{"probeError", error.what()}}).dump() << '\n';
        }
    }
    return 0;
}
